// ============================================================================
// xSPI_apb: APB4 register wrapper around xSPI_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/xSPI.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/xSPI.md
// ============================================================================
module xSPI_apb #(
  parameter int MEM_AW = 9,
  parameter int PAGE_AW = 5,
  parameter int SECT_AW = 7,
  parameter logic [4:0] DUMMY = 5'd8
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic ck,
  input logic csn,
  input logic [7:0] dq_i,
  output logic [7:0] dq_o,
  output logic dq_oe,
  output logic dqs_o,
  output logic dqs_oe
);
  localparam logic [31:0] ID_VALUE = 32'h78530100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [5:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd6) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [1:0]    c_sr;
  logic [4:0]    c_dummy;
  logic [2:0]    c_err_code;
  logic          c_irq_cmd;
  logic          c_irq_done;
  logic          c_irq_err;
  xSPI_top #(.MEM_AW(MEM_AW), .PAGE_AW(PAGE_AW), .SECT_AW(SECT_AW), .DUMMY(DUMMY)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .ck(ck),
    .csn(csn),
    .dq_i(dq_i),
    .dq_o(dq_o),
    .dq_oe(dq_oe),
    .dqs_o(dqs_o),
    .dqs_oe(dqs_oe),
    .sr(c_sr),
    .dummy(c_dummy),
    .err_code(c_err_code),
    .irq_cmd(c_irq_cmd),
    .irq_done(c_irq_done),
    .irq_err(c_irq_err)
  );

  // ---------------- registers ----------------
  logic [2:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[2:0] & wmask[2:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq_cmd;
    irq_set[1] = c_irq_done;
    irq_set[2] = c_irq_err;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'({c_err_code, c_dummy, c_sr});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
